package langsmith

// Golden-vector test of runtree.go: testdata/runtree_cases.json is replayed through the Go port and every payload
// handed to the (recording) client, every console line, thrown error and final run state must equal what the
// vendored langsmith 0.10.5 RunTree produced (testdata/runtree_golden.json, generated by
// port/tools/gen/runtree-golden.mjs). Generated run ids (low bits random) are normalised on both sides.

import (
	"bytes"
	"context"
	"errors"
	"os"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

type rtCall struct {
	client, fn, id, run, opts string
	hasOpts                   bool
}

type rtFake struct {
	name       string
	failCreate bool
	failUpdate bool
	calls      *[]rtCall
}

func (f *rtFake) createRun(ctx context.Context, run *omap, opts *destOptions) error {
	b, _, _ := stringify(run)
	*f.calls = append(*f.calls, rtCall{client: f.name, fn: "createRun", run: string(b), opts: rtOptsJSON(opts), hasOpts: opts != nil})
	if f.failCreate {
		return errors.New("fake create failure")
	}
	return nil
}

func (f *rtFake) updateRun(ctx context.Context, runID string, run *omap, opts *destOptions) error {
	b, _, _ := stringify(run)
	*f.calls = append(*f.calls, rtCall{client: f.name, fn: "updateRun", id: runID, run: string(b), opts: rtOptsJSON(opts), hasOpts: opts != nil})
	if f.failUpdate {
		return errors.New("fake update failure")
	}
	return nil
}

func rtOptsJSON(o *destOptions) string {
	if o == nil {
		return ""
	}
	m := newOmap()
	set := func(k string, v *string) {
		if v != nil {
			m.set(k, *v)
		}
	}
	set("apiKey", o.APIKey)
	set("apiUrl", o.APIURL)
	set("workspaceId", o.WorkspaceID)
	b, _, _ := stringify(m)
	return string(b)
}

func mustParse(t testing.TB, text string) any {
	t.Helper()
	v, err := rtParseJSON(text)
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	return v
}

func readTestdata(t testing.TB, name string) any {
	t.Helper()
	b, err := os.ReadFile("testdata/" + name)
	if err != nil {
		t.Fatal(err)
	}
	return mustParse(t, string(b))
}

func rtStr(v any) (string, bool) { s, ok := v.(string); return s, ok }

func rtPtrStr(m *omap, k string) *string {
	if s, ok := m.val(k).(string); ok {
		return &s
	}
	return nil
}

// specConfig converts a scenario config object (JSON, key order kept) to a runTreeConfig.
func specConfig(c *omap, fakes map[string]*rtFake, root bool) runTreeConfig {
	cfg := runTreeConfig{}
	cfg.Name, _ = rtStr(c.val("name"))
	cfg.RunType, _ = rtStr(c.val("run_type"))
	if pn, ok := c.val("project_name").(string); ok {
		cfg.ProjectName = pn
	} else if root {
		cfg.DefaultProject = true
	}
	if c.has("inputs") {
		if c.val("inputs") == nil {
			cfg.Inputs = inputsNull
		} else {
			cfg.Inputs = c.val("inputs")
		}
	}
	cfg.Metadata, _ = c.val("metadata").(*omap)
	cfg.Extra, _ = c.val("extra").(*omap)
	if tags, ok := c.val("tags").([]any); ok {
		cfg.Tags = make([]string, len(tags))
		for i, t := range tags {
			cfg.Tags[i] = t.(string)
		}
	}
	if reps, ok := c.val("replicas").([]any); ok {
		cfg.Replicas = make([]replicaConfig, len(reps))
		for i, r := range reps {
			var rc replicaConfig
			switch x := r.(type) {
			case []any: // [projectName, updates]
				if len(x) > 0 {
					pn := x[0].(string)
					rc.ProjectName = &pn
				}
				if len(x) > 1 {
					rc.Updates, _ = x[1].(*omap)
				}
			case *omap:
				rc.APIURL = rtPtrStr(x, "apiUrl")
				rc.APIKey = rtPtrStr(x, "apiKey")
				rc.ProjectName = rtPtrStr(x, "projectName")
				rc.WorkspaceID = rtPtrStr(x, "workspaceId")
				rc.Updates, _ = x.val("updates").(*omap)
				if b, ok := x.val("primary").(bool); ok {
					rc.Primary = &b
				}
				if b, ok := x.val("reroot").(bool); ok {
					rc.Reroot = &b
				}
				if name, ok := x.val("client").(string); ok {
					rc.Client = fakes[name]
				}
			}
			cfg.Replicas[i] = rc
		}
	}
	cfg.ID, _ = rtStr(c.val("id"))
	cfg.TraceID, _ = rtStr(c.val("trace_id"))
	cfg.DottedOrder, _ = rtStr(c.val("dotted_order"))
	cfg.ParentRunID, _ = rtStr(c.val("parent_run_id"))
	if st, ok := c.val("start_time").(float64); ok {
		ms := int64(st)
		cfg.StartTimeMs = &ms
	}
	return cfg
}

// rtStateJSON mirrors state() of runtree-golden.mjs.
func rtStateJSON(r *runTree) string {
	nullOr := func(v any) any {
		if jsNullish(v) {
			return nil
		}
		return v
	}
	var parentID any
	if r.parentRun != nil {
		parentID = r.parentRun.ID
	}
	var serialized, endTime, tags, events, distributed any
	if r.serializedStartTime != "" {
		serialized = r.serializedStartTime
	}
	if r.endTime != nil {
		endTime = *r.endTime
	}
	if r.tags != nil {
		tags = r.tags
	}
	if r.events != nil {
		events = r.events
	}
	if r.distributedParentID != "" {
		distributed = r.distributedParentID
	}
	reps := make([]*omap, len(r.replicas))
	for i, rep := range r.replicas {
		m := newOmap()
		if rep.APIKey != nil {
			m.set("apiKey", *rep.APIKey)
		}
		if rep.APIURL != nil {
			m.set("apiUrl", *rep.APIURL)
		}
		if rep.Primary != nil {
			m.set("primary", *rep.Primary)
		}
		if rep.ProjectName != nil {
			m.set("projectName", *rep.ProjectName)
		}
		if rep.Reroot != nil {
			m.set("reroot", *rep.Reroot)
		}
		if rep.Updates != nil {
			m.set("updates", rep.Updates)
		}
		if rep.WorkspaceID != nil {
			m.set("workspaceId", *rep.WorkspaceID)
		}
		reps[i] = m
	}
	childIDs := make([]string, len(r.childRuns))
	for i, c := range r.childRuns {
		childIDs[i] = c.ID
	}
	st := obj(
		"id", r.ID,
		"name", r.name,
		"run_type", r.runType,
		"project_name", r.projectName,
		"parent_run_id", parentID,
		"trace_id", r.traceID,
		"dotted_order", r.dottedOrder,
		"execution_order", r.executionOrder,
		"child_execution_order", r.childExecutionOrder,
		"start_time", r.startTime,
		"serialized_start_time", serialized,
		"end_time", endTime,
		"error", nullOr(r.err),
		"outputs", nullOr(r.outputs),
		"inputs", r.inputs,
		"extra", r.extra,
		"tags", tags,
		"events", events,
		"replicas", reps,
		"child_run_ids", childIDs,
		"distributed_parent_id", distributed,
	)
	b, _, _ := stringify(st)
	return string(b)
}

type rtResult struct {
	errs    []string // "" for no error, else "<name>|<message>"
	calls   []rtCall
	logs    []string // lines
	states  []string
	toJSONs []string
}

var rtGenID = regexp.MustCompile(`([0-9a-f]{8}-[0-9a-f]{4})-7000-8000-[0-9a-f]{12}`)

// normalizer replaces each generated uuid by a placeholder numbered by first appearance.
type normalizer map[string]string

func (n normalizer) apply(s string) string {
	return rtGenID.ReplaceAllStringFunc(s, func(m string) string {
		p, ok := n[m]
		if !ok {
			p = m[:13] + "-<gen:" + strconv.Itoa(len(n)) + ">"
			n[m] = p
		}
		return p
	})
}

func rtResetEnv(t *testing.T, env *omap) {
	for _, kv := range os.Environ() {
		k := kv[:strings.IndexByte(kv, '=')]
		if strings.HasPrefix(k, "LANGSMITH_") || strings.HasPrefix(k, "LANGCHAIN_") {
			t.Setenv(k, "")
			os.Unsetenv(k)
		}
	}
	for _, k := range env.ownKeys() {
		t.Setenv(k, env.vals[k].(string))
	}
}

func rtErrDesc(err error) string {
	if err == nil {
		return ""
	}
	name := "Error"
	if n, ok := err.(namedError); ok {
		name = n.ErrorName()
	}
	return name + "|" + err.Error()
}

// resetRtSeams installs the clock, the runtime environment and the stderr buffer and returns the restore func.
func resetRtSeams(clock *int64, runtimeEnv *omap, buf *bytes.Buffer) func() {
	oldNow, oldEnv := rtNow, rtRuntimeEnv
	rtNow = func() int64 { return *clock }
	rtRuntimeEnv = func() *omap { return runtimeEnv }
	oldErr := swapStderr(buf)
	warnedMu.Lock()
	clear(warnedMessages)
	warnedMu.Unlock()
	return func() { rtNow, rtRuntimeEnv = oldNow, oldEnv; swapStderr(oldErr) }
}

// runSpecCase replays one scenario through the Go port.
func runSpecCase(t *testing.T, cs *omap, runtimeEnv *omap) rtResult {
	t.Helper()
	var res rtResult
	var buf bytes.Buffer
	var calls []rtCall
	envObj, _ := cs.val("env").(*omap)
	rtResetEnv(t, envObj)
	clock := int64(cs.val("now").(float64))
	cl, _ := cs.val("client").(*omap)
	boolOf := func(k string) bool { b, _ := cl.val(k).(bool); return b }
	main := &rtFake{name: "main", failCreate: boolOf("failCreate"), failUpdate: boolOf("failUpdate"), calls: &calls}
	alt := &rtFake{name: "alt", failCreate: boolOf("failAlt"), calls: &calls}
	fakes := map[string]*rtFake{"main": main, "alt": alt}
	defer resetRtSeams(&clock, runtimeEnv, &buf)()

	runs := map[string]*runTree{}
	var order []string
	ctx := context.Background()
	for _, sv := range cs.val("steps").([]any) {
		step := sv.(*omap)
		op, _ := step.val("op").(string)
		var err error
		switch op {
		case "root":
			cfg := specConfig(step.val("config").(*omap), fakes, true)
			cfg.Client = main
			var r *runTree
			r, err = newRunTree(cfg)
			if err == nil {
				runs[step.val("as").(string)] = r
				order = append(order, step.val("as").(string))
			}
		case "child":
			c := step.val("config").(*omap)
			n := 1
			if cnt, ok := c.val("count").(float64); ok {
				n = int(cnt)
			}
			var last *runTree
			for i := 0; i < n && err == nil; i++ {
				last, err = runs[step.val("of").(string)].createChild(specConfig(c, fakes, false))
			}
			if err == nil {
				runs[step.val("as").(string)] = last
				order = append(order, step.val("as").(string))
			}
		case "post":
			r := runs[step.val("run").(string)]
			if b, ok := step.val("excludeChildRuns").(bool); ok {
				r.postRunWith(ctx, b)
			} else {
				r.postRun(ctx)
			}
		case "patch":
			r := runs[step.val("run").(string)]
			var ex *bool
			if b, ok := step.val("excludeInputs").(bool); ok {
				ex = &b
			}
			err = r.patchRunWith(ctx, ex)
		case "end":
			r := runs[step.val("run").(string)]
			var outputs any = undef
			if step.has("outputs") {
				outputs = step.val("outputs")
			}
			var errMsg *string
			if s, ok := step.val("error").(string); ok {
				errMsg = &s
			}
			var endTime *int64
			if f, ok := step.val("endTime").(float64); ok {
				ms := int64(f)
				endTime = &ms
			}
			md, _ := step.val("metadata").(*omap)
			r.endAt(outputs, errMsg, endTime, md)
		case "event":
			r := runs[step.val("run").(string)]
			if msg, ok := step.val("message").(string); ok {
				r.addEventMessage(msg)
			} else {
				kw, _ := step.val("kwargs").(*omap)
				r.addEvent(step.val("name").(string), kw)
			}
		case "now":
			clock = int64(step.val("ms").(float64))
		case "set":
			runs[step.val("run").(string)].distributedParentID = step.val("distributedParentId").(string)
		case "toJSON":
			b, _, _ := stringify(runs[step.val("run").(string)].toJSON())
			res.toJSONs = append(res.toJSONs, string(b))
		default:
			t.Fatalf("unknown op %q", op)
		}
		res.errs = append(res.errs, rtErrDesc(err))
	}
	res.calls = calls
	if buf.Len() > 0 {
		res.logs = strings.Split(strings.TrimSuffix(buf.String(), "\n"), "\n")
	}
	for _, name := range order {
		res.states = append(res.states, rtStateJSON(runs[name]))
	}
	return res
}

func TestRunTreeGolden(t *testing.T) {
	cases := readTestdata(t, "runtree_cases.json").([]any)
	golden := readTestdata(t, "runtree_golden.json").(*omap)
	runtimeEnv := golden.val("runtimeEnv").(*omap)
	gcases := golden.val("cases").([]any)
	if len(gcases) != len(cases) {
		t.Fatalf("cases %d, golden %d", len(cases), len(gcases))
	}
	for i := range cases {
		cs := cases[i].(*omap)
		g := gcases[i].(*omap)
		name := cs.val("name").(string)
		if g.val("name") != name {
			t.Fatalf("golden case %d is %v, want %q", i, g.val("name"), name)
		}
		t.Run(name, func(t *testing.T) {
			got := runSpecCase(t, cs, runtimeEnv)
			gn, wn := normalizer{}, normalizer{}

			wantErrs := g.val("results").([]any)
			if len(wantErrs) != len(got.errs) {
				t.Fatalf("steps: got %d results, want %d", len(got.errs), len(wantErrs))
			}
			for k, w := range wantErrs {
				want := ""
				if e, ok := w.(*omap); ok {
					want = e.val("name").(string) + "|" + e.val("message").(string)
				}
				if got.errs[k] != want {
					t.Errorf("step %d error: got %q, want %q", k, got.errs[k], want)
				}
			}

			wantCalls := g.val("calls").([]any)
			if len(wantCalls) != len(got.calls) {
				t.Errorf("client calls: got %d, want %d", len(got.calls), len(wantCalls))
			}
			for k := 0; k < len(wantCalls) && k < len(got.calls); k++ {
				w := wantCalls[k].(*omap)
				c := got.calls[k]
				if w.val("client") != c.client || w.val("fn") != c.fn {
					t.Errorf("call %d: got %s %s, want %v %v", k, c.client, c.fn, w.val("client"), w.val("fn"))
					continue
				}
				if c.fn == "updateRun" && wn.apply(w.val("id").(string)) != gn.apply(c.id) {
					t.Errorf("call %d id: got %s, want %v", k, c.id, w.val("id"))
				}
				wantOpts, _ := w.val("opts").(string)
				if c.opts != wantOpts || c.hasOpts != (w.val("opts") != nil) {
					t.Errorf("call %d opts: got %q (set %v), want %v", k, c.opts, c.hasOpts, w.val("opts"))
				}
				wantRun := wn.apply(w.val("run").(string))
				if gotRun := gn.apply(c.run); gotRun != wantRun {
					t.Errorf("call %d (%s) payload differs:\n got: %s\nwant: %s", k, c.fn, gotRun, wantRun)
				}
			}

			wantLogs, _ := g.val("logs").([]any)
			if len(wantLogs) != len(got.logs) {
				t.Errorf("console lines: got %q, want %d entries", got.logs, len(wantLogs))
			}
			for k := 0; k < len(wantLogs) && k < len(got.logs); k++ {
				w := wantLogs[k].(*omap)
				msg := w.val("msg").(string)
				line := got.logs[k]
				if w.val("kind") == "warn" {
					if line != msg {
						t.Errorf("warn %d: got %q, want %q", k, line, msg)
					}
					continue
				}
				detail, _ := w.val("detail").(string)
				if !strings.HasPrefix(line, msg+" ") || !strings.HasSuffix(line, detail) {
					t.Errorf("error %d: got %q, want prefix %q suffix %q", k, line, msg, detail)
				}
			}

			wantStates := g.val("states").([]any)
			if len(wantStates) != len(got.states) {
				t.Fatalf("states: got %d, want %d", len(got.states), len(wantStates))
			}
			for k := range wantStates {
				if w, g := wn.apply(wantStates[k].(string)), gn.apply(got.states[k]); w != g {
					t.Errorf("state %d differs:\n got: %s\nwant: %s", k, g, w)
				}
			}
			wantJSONs, _ := g.val("toJSONs").([]any)
			if len(wantJSONs) != len(got.toJSONs) {
				t.Fatalf("toJSON: got %d, want %d", len(got.toJSONs), len(wantJSONs))
			}
			for k := range wantJSONs {
				if w, g := wn.apply(wantJSONs[k].(string)), gn.apply(got.toJSONs[k]); w != g {
					t.Errorf("toJSON %d differs:\n got: %s\nwant: %s", k, g, w)
				}
			}
		})
	}
}
